 993: # The members of this detached run - all of them (a panel once its numbers are assigned, a single
 994: # run once its reviewer and numbers are known), saved.
 995: function Set-DetachedMembers {
 996:     param([object[]]$Members)
 997:     if (-not $script:DetachRun) { return }
 998:     $script:DetachRun.Record.members = [object[]]@($Members | Where-Object { $_ })
 999:     Save-DetachedRun
1000: }
