1061: # The foreground of -Detach once every check passed (D1, D5, D8): picks the detach id, writes the
1062: # `starting` record ONCE, starts the background, prints three lines and exits 0 - or refuses (exit
1063: # 1) with nothing left behind. $Members: the planned members (pending; a roster-skipped entry
1064: # skipped); $Budget: D4; $Plan: what runs; $BriefFull, $ArtifactFull: absolute (D8); $Warnings:
1065: # what a real run prints before it starts. Reads the run's variables ($taskDir, $collabRoot,
1066: # $callerCwd, $Task, $Purpose, $ReplyName).
1067: function Start-DetachedRun {
1068:     param([string]$Kind, [object[]]$Members, [int]$Budget, [string]$Plan, [string]$BriefFull = '', [string[]]$ArtifactFull = @(), [string[]]$Warnings = @())
1069:     # The background's arguments: this call's, minus -Detach, with the paths absolute (D8).
1070:     $bgArgs = @{}
1071:     foreach ($k in $script:ScriptBound.Keys) {
1072:         if ($k -eq 'Detach' -or $script:CommonParameterNames -contains $k) { continue }
1073:         $bgArgs[$k] = $script:ScriptBound[$k]
1074:     }
1075:     if ($BriefFull) { $bgArgs['Brief'] = $BriefFull }
1076:     if (@($ArtifactFull).Count -gt 0) { $bgArgs['Artifact'] = [string[]]@($ArtifactFull) }
1077:     $bgArgs['CollabDir'] = $collabRoot
1078:     # The id: a guid whose id8 names no status or log file of the task yet (D7). TEST HOOK:
1079:     # CODEX_CONSULT_TEST_DETACH_GUIDS=<guid>[,<guid>...] - tried first, in that order.
1080:     $tries = New-Object System.Collections.Generic.List[string]
1081:     foreach ($g in ((Get-TestHookValue 'CODEX_CONSULT_TEST_DETACH_GUIDS')).Split(',')) {
1082:         if ($g.Trim() -match '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') { $tries.Add($g.Trim().ToLowerInvariant()) }
1083:     }
1084:     for ($i = 0; $i -lt 16; $i++) { $tries.Add([guid]::NewGuid().ToString()) }
1085:     try { [void][IO.Directory]::CreateDirectory($taskDir) } catch { Stop-WithError "could not create the task directory '$taskDir' ($(ConvertTo-OneLine $_.Exception.Message)); nothing was started." }
1086:     $newId = ''
1087:     $paths = $null
1088:     foreach ($cand in $tries) {
1089:         $p = Get-DetachedPaths -TaskDir $taskDir -Id $cand
1090:         if ((Test-Path -LiteralPath $p.Status) -or (Test-Path -LiteralPath $p.Log) -or (Test-Path -LiteralPath $p.Prompt)) { continue }
1091:         $newId = $cand
1092:         $paths = $p
1093:         break
1094:     }
1095:     if (-not $newId) { Stop-WithError "no free detach id for task '$Task' (the status or log file of every candidate exists); nothing was started." }
1096:     # (wave 26, F11-2) an inline -Prompt goes to <task>/.consult.detached-<id8>.prompt.txt (UTF-8,
1097:     # gitignored like the log); the record's args name only that file (PromptFile), so a run that
1098:     # never starts leaves no prompt text in its status file - the background reads the file and
1099:     # removes it; -Status -Prune removes a left-over one with the run's other files
1100:     $promptFile = ''
1101:     if ($bgArgs.ContainsKey('Prompt') -and [string]$bgArgs['Prompt']) {
1102:         $promptFile = $paths.Prompt
1103:         try { Write-Utf8NoBom -Path $promptFile -Text ([string]$bgArgs['Prompt']) } catch {
1104:             Stop-WithError "could not write the prompt file '$promptFile' ($(ConvertTo-OneLine $_.Exception.Message)); nothing was started."
1105:         }
1106:         $bgArgs.Remove('Prompt')
1107:         $bgArgs['PromptFile'] = $promptFile
1108:     }
1109:     # The background's command line.
1110:     $hostExe = (Get-Process -Id $PID).Path
1111:     $bgLine = ''
1112:     if ($script:OnWindows) {
1113:         # cmd.exe would expand a %NAME% in these paths: refused rather than corrupted
1114:         foreach ($pth in @($hostExe, $script:SelfPath, $collabRoot, $paths.Log)) {
1115:             if ($pth.Contains('%')) { Stop-WithError "-Detach starts its background through cmd.exe, which would expand the '%' in '$pth'; run without -Detach; nothing was started." }
1116:         }
1117:         $collabArg = $collabRoot
1118:         # a trailing backslash would escape the closing quote
1119:         if ($collabArg.EndsWith('\')) { $collabArg += '.' }
1120:         $inner = '"' + $hostExe + '" -NoProfile -ExecutionPolicy Bypass -File "' + $script:SelfPath + '" -Task ' + $Task + ' -CollabDir "' + $collabArg + '" -DetachId ' + $newId + ' <NUL 1>"' + $paths.Log + '" 2>&1'
1121:         $bgLine = '/d /v:off /s /c "' + $inner + '"'
1122:     } else {
1123:         $q = { param([string]$s) "'" + $s.Replace("'", "'\''") + "'" }
1124:         $bgLine = 'exec nohup ' + (& $q $hostExe) + ' -NoProfile -File ' + (& $q $script:SelfPath) + ' -Task ' + (& $q $Task) + ' -CollabDir ' + (& $q $collabRoot) + ' -DetachId ' + $newId + ' </dev/null >' + (& $q $paths.Log) + ' 2>&1'
1125:     }
1126:     # The `starting` record, written ONCE, before the background exists (D5).
1127:     $rec = ConvertTo-DetachedRecord @{
1128:         status_version = $script:DetachedStatusVersion; id = $newId; id8 = $paths.Id8; task = $Task; kind = $Kind; state = 'starting'
1129:         started = (Get-IsoTimestamp); host = [Environment]::MachineName; budget_sec = $Budget; purpose = $Purpose; reply_name = $ReplyName
1130:         brief = $BriefFull; members = [object[]]@($Members | Where-Object { $_ }); log = $paths.Log; args = (ConvertTo-DetachArgs -Arguments $bgArgs)
1131:         # (wave 27, R13) the coordinator resolved here and the markers the background never gets
1132:         coordinator = $coordinatorRecord; child_env_scrubbed = [object[]]@($childEnvScrubbed)
1133:     }
1134:     try { Write-DetachedStatus -Path $paths.Status -Record $rec } catch {
1135:         $why = ConvertTo-OneLine $_.Exception.Message
1136:         if ($promptFile) { $null = Remove-PendingFile -Path $promptFile }
1137:         Stop-WithError "could not write the status file '$($paths.Status)' ($why); nothing was started."
1138:     }
1139:     # (wave 27, R13 D4) the background (and so every engine child of it) starts without the
1140:     # coordinator's host markers; this process gets them back right after the start
1141:     $bgHidden = $null
1142:     try {
1143:         $bgHidden = Hide-HostMarkers
1144:         if ($script:OnWindows) {
1145:             $cmdExe = [string]$env:ComSpec
1146:             if (-not $cmdExe) { $cmdExe = 'cmd.exe' }
1147:             # ShellExecute (no -NoNewWindow, no redirection here): the background inherits none of
1148:             # this process's handles, so the caller's pipes close when this process exits
1149:             $null = Start-Process -FilePath $cmdExe -ArgumentList $bgLine -WorkingDirectory $callerCwd -WindowStyle Hidden -PassThru
1150:         } else {
1151:             $psi = New-Object System.Diagnostics.ProcessStartInfo
1152:             $psi.FileName = '/bin/sh'
1153:             [void]$psi.ArgumentList.Add('-c')
1154:             [void]$psi.ArgumentList.Add($bgLine)
1155:             $psi.UseShellExecute = $false
1156:             $psi.WorkingDirectory = $callerCwd
1157:             # (wave 27c, D4) the block must come out clean, else the start is refused
1158:             $scrub = Remove-HostMarkersFromStartInfo $psi -KeepTestVars
1159:             if ($scrub) { throw "host markers could not be hidden ($scrub)" }
1160:             $null = [System.Diagnostics.Process]::Start($psi)
1161:         }
1162:     } catch {
1163:         Restore-HostMarkers -Saved $bgHidden
1164:         $bgHidden = $null1219:             if ($null -ne $m.n) { $details.Add("n=$($m.n)") }
1220:             if ($m.handoff) { $details.Add("handoff $($m.handoff)") }
1221:             if ($null -ne $m.wall_seconds) { $details.Add("$($m.wall_seconds) s") }
1222:             Write-Host ("  #{0} {1} - {2}{3}{4}" -f $m.position, $m.lineage, $m.state, $(if ($outcome) { ": $outcome" } else { '' }), $(if ($details.Count -gt 0) { " ($($details.ToArray() -join ', '))" } else { '' }))
1223:         }
1224:         Write-Host "  log: $(if ($rec.log) { $rec.log } else { $run.Log })"
1225:         if ($j.State -eq 'done' -and $rec.summary) {
1226:             Write-Host ''
1227:             foreach ($l in ([string]$rec.summary -split "`n")) { Write-Host $l }
1228:         }
1229:     }
1230: }
