237: # ----------------------------------------------------------------------------- detached runs (wave 25, R12): the readers
238: #
239: # codex-consult.ps1 -Detach checks a consultation like a real run in the caller's process (the
240: # dry run's checks plus those a real run makes before it takes the task lock - D2), then runs it
241: # in a BACKGROUND process and returns at once. The run's state is its status file
242: # <task>/.consult.detached-<id8>.status.json (atomic replace; <id8> = the first 8 hex digits of
243: # the detach id, a guid), its console output (stdout and stderr) the log
244: # <task>/.consult.detached-<id8>.log. Both names start with .consult.: Get-CollabSnapshot leaves
245: # them out (an agy or muse member's tree check never sees them), the collab directory is outside
246: # the tree fingerprint, and .gitignore carries .consult.detached-* (D1).
247: # Writers (D5): the foreground writes `starting` (no pid) ONCE, before it launches the
248: # background, never after; from then on only the background writes - its self-report `running`
249: # {pid, start_time, host} first, the members as they start and finish, `done` {exit, summary} on
250: # EVERY exit path (D3); `codex-consult.ps1 -Status -Prune` deletes the files of runs that are done
251: # or died, 7 days after (D6) - (wave 26, F07-1) an unreadable status file too, 7 days after the
252: # file was last written. Readers - -Status, -Wait, codex-findings.ps1 -List, the SessionStart
253: # hook - judge a record that is not done by its background's liveness (Get-DetachedJudgement, D6);
254: # a background on another host is never judged (D11).
255: #
256: # The record (status_version 1), fields in this order: status_version, id (the guid), id8, task,
257: # kind (run | panel), state (starting | running | done), exit (null until done), started (the
258: # foreground's clock), updated, finished, wall_seconds, pid, start_time (the background's: UTC
259: # round trip), host, budget_sec (D4 - -Wait's default timeout), purpose, reply_name, brief,
260: # members[{position (the roster position; 1 without a roster), lineage, state (D11: pending |
261: # running | usable | failed | skipped | killed | blocked | commit_blocked | orphan), outcome (the
262: # panel's Get-PanelMemberStatus phrase; a single run: its bridge outcome), wall_seconds, n,
263: # handoff (NN), reply}], summary (the summary block the run printed - a single run: its outcome
264: # lines up to `events file:`; a panel: its `Panel <id8>: ...` block - else its last error line),
265: # log, args (only in the foreground's `starting` record: the background's parameters, base64 of
266: # UTF-8 PowerShell CLIXML; the self-report drops it).
267: 
268: $script:DetachedStatusVersion = 1
269: # D5: a `starting` record without a pid reads "starting" this long, then "never started"
270: $script:DetachedStartGraceSec = 60
271: # D6: -Status -Prune removes the runs that are done or died after this many days
272: $script:DetachedPruneDays = 7
273: # D11: a member's state
274: $script:DetachedMemberStates = @('pending', 'running', 'usable', 'failed', 'skipped', 'killed', 'blocked', 'commit_blocked', 'orphan')
275: # "k of N members finished": the member states that count as finished (a skipped entry never ran)
276: $script:DetachedMemberDone = @('usable', 'failed', 'killed', 'blocked', 'commit_blocked', 'orphan')
277: 
278: # The files of a detached run: { Id8; Status; Log; Prompt (wave 26, F11-2: the inline -Prompt of
279: # a run that has not started yet) }.
280: function Get-DetachedPaths {
281:     param([string]$TaskDir, [string]$Id)
282:     $id8 = ([string]$Id).Replace('-', '')
283:     if ($id8.Length -gt 8) { $id8 = $id8.Substring(0, 8) }
284:     $id8 = $id8.ToLowerInvariant()
285:     return [pscustomobject]@{ Id8 = $id8; Status = (Join-Path $TaskDir ".consult.detached-$id8.status.json"); Log = (Join-Path $TaskDir ".consult.detached-$id8.log"); Prompt = (Join-Path $TaskDir ".consult.detached-$id8.prompt.txt") }
286: }
