289: function New-DetachedMember {
290:     param([int]$Position, [string]$Lineage, [string]$State = 'pending', [string]$Outcome = '', $Wall = $null, $N = $null, [string]$Handoff = '', [string]$Reply = '')
291:     return [pscustomobject]@{ position = $Position; lineage = $Lineage; state = $State; outcome = $Outcome; wall_seconds = $Wall; n = $N; handoff = $Handoff; reply = $Reply } 321:     $parsed = 0
322:     if ([int]::TryParse([string](Get-PropertyValue $Record 'pid' ''), [ref]$parsed) -and $parsed -gt 0) { $pidValue = $parsed }
323:     $exitValue = $null
324:     if ([int]::TryParse([string](Get-PropertyValue $Record 'exit' ''), [ref]$parsed)) { $exitValue = $parsed }
325:     $budget = 0
326:     [void][int]::TryParse([string](Get-PropertyValue $Record 'budget_sec' ''), [ref]$budget)
327:     $version = $script:DetachedStatusVersion
328:     if ([int]::TryParse([string](Get-PropertyValue $Record 'status_version' ''), [ref]$parsed)) { $version = $parsed }
329:     return [pscustomobject]@{
330:         status_version = $version
331:         id             = [string](Get-PropertyValue $Record 'id' '')
332:         id8            = [string](Get-PropertyValue $Record 'id8' '')
333:         task           = [string](Get-PropertyValue $Record 'task' '')
334:         kind           = [string](Get-PropertyValue $Record 'kind' 'run')
335:         state          = [string](Get-PropertyValue $Record 'state' '')
336:         exit           = $exitValue
337:         started        = (ConvertTo-DetachedTime (Get-PropertyValue $Record 'started' $null))
338:         updated        = (ConvertTo-DetachedTime (Get-PropertyValue $Record 'updated' $null))
339:         finished       = (ConvertTo-DetachedTime (Get-PropertyValue $Record 'finished' $null))
340:         wall_seconds   = (Get-PropertyValue $Record 'wall_seconds' $null)
341:         pid            = $pidValue
342:         start_time     = (ConvertTo-DetachedTime (Get-PropertyValue $Record 'start_time' $null) -RoundTrip)
343:         host           = [string](Get-PropertyValue $Record 'host' '')
344:         budget_sec     = $budget
345:         purpose        = [string](Get-PropertyValue $Record 'purpose' '')
346:         reply_name     = [string](Get-PropertyValue $Record 'reply_name' '')
347:         brief          = [string](Get-PropertyValue $Record 'brief' '')
348:         members        = [object[]]$members.ToArray()
349:         summary        = [string](Get-PropertyValue $Record 'summary' '')
350:         log            = [string](Get-PropertyValue $Record 'log' '')
351:         args           = $(if ([string](Get-PropertyValue $Record 'args' '')) { [string]$Record.args } else { $null })
352:         # (wave 27, R13 D3/D4) the coordinator the foreground resolved and the host markers it kept
353:         # from the background: the run takes both from here (its own environment has no markers)
354:         coordinator        = (Get-PropertyValue $Record 'coordinator' $null)
355:         child_env_scrubbed = [object[]]@(@(Get-PropertyValue $Record 'child_env_scrubbed' @()) | Where-Object { $_ } | ForEach-Object { [string]$_ })
356:     }
