359: # { Exists; Record (canonical); Error }. Absent -> Exists $false. Present but empty,
360: # unparseable, not an object, without an id or with a state other than starting | running |
361: # done -> Error.
362: function Read-DetachedStatus {
363:     param([string]$Path)
364:     if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return [pscustomobject]@{ Exists = $false; Record = $null; Error = '' } }
365:     $text = Read-SharedText -Path $Path
366:     $obj = $null
367:     $why = ''
368:     if (-not $text.Trim()) { $why = 'it is empty or could not be read' }
369:     else {
370:         try { $obj = ConvertFrom-Json -InputObject $text } catch { $why = "it does not parse: $(ConvertTo-OneLine $_.Exception.Message)" }
371:         if (-not $why -and -not (Test-IsJsonObject $obj)) { $why = 'it is not a JSON object' }
372:         if (-not $why -and -not [string](Get-PropertyValue $obj 'id' '')) { $why = 'it names no id' }
373:         if (-not $why -and @('starting', 'running', 'done') -notcontains [string](Get-PropertyValue $obj 'state' '')) { $why = "its state '$(Get-PropertyValue $obj 'state' '')' is not one of starting|running|done" }
374:     }
375:     if ($why) { return [pscustomobject]@{ Exists = $true; Record = $null; Error = "the status file '$Path' cannot be used: $why" } }
376:     return [pscustomobject]@{ Exists = $true; Record = (ConvertTo-DetachedRecord $obj); Error = '' }
377: }
