379: # Every detached run of a task, newest first (by `started`, else the file time; then by id8):
380: # { Path; Id8; Record; Error; When; Log }. An atomic-write temp is not a run.
381: function Read-DetachedRuns {
382:     param([string]$TaskDir)
383:     $runs = New-Object System.Collections.Generic.List[object]
384:     if (-not $TaskDir -or -not [IO.Directory]::Exists($TaskDir)) { return , ([object[]]@()) }
385:     foreach ($f in [IO.Directory]::GetFiles($TaskDir, '.consult.detached-*.status.json')) {
386:         $name = [IO.Path]::GetFileName($f)
387:         if ($name -notmatch '^\.consult\.detached-([0-9A-Za-z]+)\.status\.json$') { continue }
388:         $id8 = $Matches[1].ToLowerInvariant()
389:         $rd = Read-DetachedStatus -Path $f
390:         $when = $null
391:         if ($rd.Record) { $when = ConvertTo-WhenOffset $rd.Record.started }
392:         if ($null -eq $when) { try { $when = [DateTimeOffset]([IO.File]::GetLastWriteTimeUtc($f)) } catch { $when = [DateTimeOffset]::MinValue } }
393:         $runs.Add([pscustomobject]@{ Path = $f; Id8 = $id8; Record = $rd.Record; Error = $rd.Error; When = $when; Log = (Join-Path $TaskDir ".consult.detached-$id8.log") })
394:     }
395:     $sorted = @($runs | Sort-Object -Property @{ Expression = { $_.When }; Descending = $true }, @{ Expression = { $_.Id8 }; Descending = $false })
396:     return , ([object[]]$sorted)
397: }
