399: # "45 s" | "12 min" | "2 h 05 min" | "3 d 04 h"
400: function Format-DetachedSpan {
401:     param([TimeSpan]$Span)
402:     if ($Span.TotalSeconds -lt 0) { $Span = [TimeSpan]::Zero }
403:     if ($Span.TotalSeconds -lt 90) { return "$([int][Math]::Floor($Span.TotalSeconds)) s" }
404:     if ($Span.TotalMinutes -lt 90) { return "$([int][Math]::Floor($Span.TotalMinutes)) min" }
405:     if ($Span.TotalHours -lt 48) { return ('{0} h {1:D2} min' -f [int][Math]::Floor($Span.TotalHours), $Span.Minutes) }
406:     return ('{0} d {1:D2} h' -f [int][Math]::Floor($Span.TotalDays), $Span.Hours)
407: }
