409: # The verdict on one detached run (D5, D6, D11): { State; Exit; Text; Finished; Of }
410: #   done           the run ended: Exit 0 when its exit was 0, else 1
411: #   running        not done, its background (pid + start time, on this host) is alive: Exit 2
412: #   elsewhere      not done, its background runs on another host: liveness cannot be checked
413: #                  from here and is never judged: Exit 2
414: #   starting       written by the foreground (no pid yet) less than 60 s ago: Exit 2
415: #   died           not done, and its background is gone: Exit 1 (its recovery records are
416: #                  judged by the next run of the task as usual)
417: #   never-started  still `starting` without a pid after 60 s: Exit 1
418: #   unreadable     the status file cannot be used ($Problem): Exit 1
419: # Finished / Of: its members that finished / that run (a roster-skipped entry does not run; a
420: # member the run never started - skipped "not started: ..." - counts as run and finished).
421: function Get-DetachedJudgement {
422:     param($Record, [string]$Problem = '', [DateTimeOffset]$Now = [DateTimeOffset]::Now)
423:     if ($Problem -or $null -eq $Record) {
424:         $text = $Problem
425:         if (-not $text) { $text = 'no status record' }
426:         return [pscustomobject]@{ State = 'unreadable'; Exit = 1; Text = $text; Finished = 0; Of = 0 }
427:     }
428:     $members = @($Record.members | Where-Object { $_ })
429:     $notStarted = { param($m) [string]$m.state -eq 'skipped' -and [string]$m.outcome -match '^not started' }
430:     $of = @($members | Where-Object { [string]$_.state -ne 'skipped' -or (& $notStarted $_) }).Count
431:     $finished = @($members | Where-Object { $script:DetachedMemberDone -contains [string]$_.state -or (& $notStarted $_) }).Count
432:     $started = ConvertTo-WhenOffset $Record.started
433:     $startedText = $(if ($Record.started) { [string]$Record.started } else { '(unknown)' })
434:     $state = [string]$Record.state
435:     if ($state -eq 'done') {
436:         $code = $Record.exit
437:         $exitText = $(if ($null -eq $code) { 'unknown' } else { [string]$code })
438:         $ok = ($null -ne $code -and [int]$code -eq 0)
439:         return [pscustomobject]@{ State = 'done'; Exit = $(if ($ok) { 0 } else { 1 }); Text = "done, exit $exitText"; Finished = $finished; Of = $of }
440:     }
441:     $bgPid = 0
442:     if ($null -ne $Record.pid) { $bgPid = [int]$Record.pid }
443:     if ($bgPid -le 0) {
444:         $age = $(if ($started) { $Now - $started } else { [TimeSpan]::MaxValue })
445:         if ($age.TotalSeconds -lt $script:DetachedStartGraceSec) {
446:             return [pscustomobject]@{ State = 'starting'; Exit = 2; Text = "starting - the background has not reported yet (started $(Format-DetachedSpan $age) ago)"; Finished = $finished; Of = $of }
447:         }
