473: # The SessionStart hook's phrase over every task of the collab root (D6): '' when no detached run
474: # is running, died or finished in the last $FinishedHours hours; else e.g. "; 1 detached
475: # consultation running (task t)" or "; detached consultations: 1 running (task t), 1 finished
476: # (task u)". Status files only; nothing is written.
477: function Get-DetachedPhrase {
478:     param([string]$CollabRoot, [DateTimeOffset]$Now = [DateTimeOffset]::Now, [int]$FinishedHours = 24)
479:     if (-not $CollabRoot -or -not [IO.Directory]::Exists($CollabRoot)) { return '' }
480:     $tasksOf = @{ running = (New-Object System.Collections.Generic.List[string]); finished = (New-Object System.Collections.Generic.List[string]); died = (New-Object System.Collections.Generic.List[string]) }
481:     $counts = @{ running = 0; finished = 0; died = 0 }
482:     foreach ($dir in [IO.Directory]::GetDirectories($CollabRoot)) {
483:         $task = [IO.Path]::GetFileName($dir)
484:         foreach ($run in (Read-DetachedRuns -TaskDir $dir)) {
485:             $j = Get-DetachedJudgement -Record $run.Record -Problem ([string]$run.Error) -Now $Now
486:             $cat = ''
487:             if (@('running', 'elsewhere', 'starting') -contains $j.State) { $cat = 'running' }
488:             elseif (@('died', 'never-started', 'unreadable') -contains $j.State) { $cat = 'died' }
489:             else {
490:                 $fin = ConvertTo-WhenOffset $run.Record.finished
491:                 if ($fin -and ($Now - $fin).TotalHours -lt $FinishedHours) { $cat = 'finished' }
492:             }
493:             if (-not $cat) { continue }
494:             $counts[$cat]++
495:             if (-not $tasksOf[$cat].Contains($task)) { $tasksOf[$cat].Add($task) }
496:         }
497:     }
498:     $parts = New-Object System.Collections.Generic.List[string]
499:     foreach ($cat in @('running', 'finished', 'died')) {
500:         if ($counts[$cat] -eq 0) { continue }
501:         $tasks = @($tasksOf[$cat])
502:         $shown = ($tasks | Select-Object -First 3) -join ', '
503:         if ($tasks.Count -gt 3) { $shown += ', ...' }
504:         $parts.Add("$cat ($(if ($tasks.Count -eq 1) { 'task' } else { 'tasks' }) $shown)")
505:     }
506:     if ($parts.Count -eq 0) { return '' }
507:     $total = $counts.running + $counts.finished + $counts.died
508:     if ($parts.Count -eq 1) {
509:         return "; $total detached consultation$(if ($total -ne 1) { 's' }) $($parts[0])"
510:     }
511:     $withCounts = @(foreach ($cat in @('running', 'finished', 'died')) { if ($counts[$cat] -gt 0) { "$($counts[$cat]) " + (@($parts | Where-Object { $_.StartsWith("$cat ") }) | Select-Object -First 1) } })
512:     return "; detached consultations: $($withCounts -join ', ')"
513: }

1185:     exit 4
