1208:         if ($rec.purpose) { $what += ", purpose $($rec.purpose)" }
1209:         if ($rec.reply_name) { $what += ", reply name $($rec.reply_name)" }
1210:         Write-Host "detached $($run.Id8) ($what): $($j.Text)"
1211:         $pidText = $(if ($rec.pid) { "pid $($rec.pid) on $($rec.host)" } else { "no background pid yet (host $($rec.host))" })
1212:         $wallText = $(if ($j.State -eq 'done' -and $null -ne $rec.wall_seconds) { "; wall $($rec.wall_seconds) s" } else { '' })
1213:         Write-Host "  detach id $($rec.id), started $($rec.started), $pidText; budget $($rec.budget_sec) s$wallText"
1214:         foreach ($m in @($rec.members | Where-Object { $_ })) {
1215:             $outcome = [string]$m.outcome
1216:             if ($outcome.StartsWith("$($m.state): ")) { $outcome = $outcome.Substring(([string]$m.state).Length + 2) }
1217:             if ($outcome -eq [string]$m.state) { $outcome = '' }
1218:             $details = New-Object System.Collections.Generic.List[string]
1219:             if ($null -ne $m.n) { $details.Add("n=$($m.n)") }
