1540: # top-level "thread_id" field. The other shapes below are version-drift safety nets,
1541: # and they only look at SESSION-START events (type thread.started, session.started or
1542: # session_configured, top-level or msg-wrapped): any other event may carry some other
1543: # id (a parent thread, a sub-session) and is ignored for thread purposes. No thread
1544: # here -> the caller falls back to the rollout rule.
1545: $script:SessionStartEvents = @('thread.started', 'session.started', 'session_configured')
1546: function Get-ThreadIdFromEvents {
1547:     param([string]$Path)
1548:     $text = Read-SharedText -Path $Path
1549:     if (-not $text) { return '' }
1550:     $uuidRe = '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
