1552:         if (-not $line) { continue }
1553:         $trimmed = $line.Trim()
1554:         if (-not $trimmed.StartsWith('{')) { continue }
1555:         $obj = $null
1556:         try { $obj = $trimmed | ConvertFrom-Json } catch { continue }
1557:         $type = ''
1558:         if ($obj.PSObject.Properties['type']) { $type = [string]$obj.type }
1559:         # primary: the "thread.started" event
1560:         if ($type -ceq 'thread.started' -and $obj.PSObject.Properties['thread_id'] -and $obj.thread_id -match $uuidRe) {
1561:             return [string]$obj.thread_id
1562:         }
1563:         # drift net 1: a top-level session-start event with a thread/session/conversation id
1564:         if ($script:SessionStartEvents -ccontains $type) {
1565:             foreach ($field in @('thread_id', 'session_id', 'conversation_id')) {
1566:                 if ($obj.PSObject.Properties[$field] -and $obj.$field -match $uuidRe) {
1567:                     return [string]$obj.$field
1568:                 }
1569:             }
1570:         }
1571:         # drift net 2: the older msg-wrapped shape ({"msg":{"type":"session_configured",...}})
1572:         if ($obj.PSObject.Properties['msg'] -and $obj.msg -and $obj.msg.PSObject.Properties['type']) {
1573:             $msg = $obj.msg
1574:             if ($script:SessionStartEvents -ccontains [string]$msg.type) {
1575:                 foreach ($field in @('session_id', 'thread_id', 'conversation_id')) {
1576:                     if ($msg.PSObject.Properties[$field] -and $msg.$field -match $uuidRe) {
1577:                         return [string]$msg.$field
1578:                     }
1579:                 }
1580:             }
1581:         }
1582:     }
1583:     return ''
1584: }
